import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readLine())
    val n = st.nextToken().toInt()
    val t = st.nextToken().toInt()

    val maxY = 4
    // dp[pos][lastY][humps][valleys][trend]
    // trend: 0 = unknown (only at pos=1), 1 = up, 2 = down
    val dp = Array(n + 1) {
        Array(maxY + 1) {
            Array(t + 1) {
                Array(t + 1) {
                    LongArray(3)
                }
            }
        }
    }

    // Initialize for position 1: any y1 in 1..4, no humps/valleys, trend unknown
    for (y in 1..maxY) {
        dp[1][y][0][0][0] = 1L
    }

    for (pos in 2..n) {
        for (lastY in 1..maxY) {
            for (h in 0..t) {
                for (v in 0..t) {
                    for (trend in 0..2) {
                        val curCount = dp[pos - 1][lastY][h][v][trend]
                        if (curCount == 0L) continue
                        for (newY in 1..maxY) {
                            if (newY == lastY) continue // no horizontal segment
                            var newTrend = trend
                            var newH = h
                            var newV = v

                            if (trend == 0) {
                                // first step defines trend
                                newTrend = if (newY > lastY) 1 else 2
                            } else {
                                if (newY > lastY) {
                                    // going up
                                    if (trend == 2 && pos - 1 >= 2) {
                                        // valley at pos-1
                                        newV++
                                        if (newV > t) continue
                                    }
                                    newTrend = 1
                                } else {
                                    // going down
                                    if (trend == 1 && pos - 1 >= 2) {
                                        // hump at pos-1
                                        newH++
                                        if (newH > t) continue
                                    }
                                    newTrend = 2
                                }
                            }

                            dp[pos][newY][newH][newV][newTrend] += curCount
                        }
                    }
                }
            }
        }
    }

    var result = 0L
    for (lastY in 1..maxY) {
        for (trend in 1..2) { // final trend must be defined
            result += dp[n][lastY][t][t - 1][trend]
        }
    }

    println(result)
}

import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readLine())
    val n = st.nextToken().toInt()
    val t = st.nextToken().toInt()

    // dp[pos][lastY][peaks][valleys][trend]
    // trend: 0 = up, 1 = down
    val dp = Array(n + 1) { Array(5) { Array(t + 1) { Array(t) { LongArray(2) } } } }

    // Initialize for position 1
    for (y in 1..4) {
        // pos = 1, lastY = y, peaks = 0, valleys = 0, trend undefined yet
        // We will set trend on the first move (pos 2)
        // To simplify, we treat pos=1 as having both trends possible but will
        // actually set them when moving to pos=2.
        // So we store in a special way: we will handle pos=2 separately.
        // Instead, we can start transitions from pos=1 manually.
        // We'll just store a marker: trend = 0 and 1 both as starting states.
        dp[1][y][0][0][0] = 1L
        dp[1][y][0][0][1] = 1L
    }

    for (pos in 1 until n) {
        for (lastY in 1..4) {
            for (peaks in 0..t) {
                for (valleys in 0 until t) {
                    for (trend in 0..1) {
                        val cur = dp[pos][lastY][peaks][valleys][trend]
                        if (cur == 0L) continue
                        for (nextY in 1..4) {
                            if (nextY == lastY) continue // no horizontal segment
                            val newTrend = if (nextY > lastY) 0 else 1
                            var newPeaks = peaks
                            var newValleys = valleys
                            if (pos >= 2) {
                                // We have at least three points: pos-1, pos, pos+1
                                // Check if pos is peak or valley
                                // Need previous trend at pos-1 and current trend at pos
                                // But we only store trend of last segment.
                                // To detect extremum at pos, we need trend at segment (pos-1,pos)
                                // and newTrend at segment (pos,pos+1).
                                // trend is (pos-1,pos), newTrend is (pos,pos+1).
                                if (trend == 0 && newTrend == 1) {
                                    newPeaks++
                                } else if (trend == 1 && newTrend == 0) {
                                    newValleys++
                                }
                            }
                            if (newPeaks > t || newValleys >= t) continue
                            dp[pos + 1][nextY][newPeaks][newValleys][newTrend] += cur
                        }
                    }
                }
            }
        }
    }

    var result = 0L
    for (lastY in 1..4) {
        for (trend in 0..1) {
            result += dp[n][lastY][t][t - 1][trend]
        }
    }
    println(result)
}

