    val t = st.nextToken().toInt()

    // dp[pos][prevY][prevTrend][peaks][valleys]
    // prevTrend: 0 = start, 1 = up, 2 = down
    val dp = Array(n + 1) {
        Array(5) {
            Array(3) {
                Array(t + 1) {
                    LongArray(t) { 0L }
                }
            }
        }
    }

    // Initialize for position 1: choose y1 in 1..4
    for (y in 1..4) {
        dp[1][y][0][0][0] = 1L
    }

    for (pos in 2..n) {
        for (prevY in 1..4) {
            for (prevTrend in 0..2) {
                for (peaks in 0..t) {
                    for (valleys in 0 until t) {
                        val curVal = dp[pos - 1][prevY][prevTrend][peaks][valleys]
                        if (curVal == 0L) continue
                        for (y in 1..4) {
                            if (y == prevY) continue
                            val newTrend = if (y > prevY) 1 else 2
                            var newPeaks = peaks
                            var newValleys = valleys
                            if (prevTrend != 0 && prevTrend != newTrend) {
                                if (prevTrend == 1 && newTrend == 2) {
                                    newPeaks++
                                } else if (prevTrend == 2 && newTrend == 1) {
                                    newValleys++
                                }
                            }
                            if (newPeaks > t || newValleys >= t) continue
                            dp[pos][y][newTrend][newPeaks][newValleys] += curVal
                        }
                    }
                }
            }
        }
    }

    var result = 0L
    for (y in 1..4) {
        for (trend in 1..2) {
            result += dp[n][y][trend][t][t - 1]
        }
    }

    println(result)
}

import java.util.StringTokenizer

fun main() {
    val br = System.`in`.bufferedReader()
    val st = StringTokenizer(br.readLine())
    val n = st.nextToken().toInt()
    val t = st.nextToken().toInt()

    val maxY = 4
    var count = 0

    fun dfs(pos: Int, prev: Int, peaks: Int, valleys: Int, prevDiff: Int) {
        if (pos > n) {
            if (peaks == t && valleys == t - 1) count++
            return
        }

        for (y in 1..maxY) {
            if (y == prev) continue
            val diff = y - prev
            var newPeaks = peaks
            var newValleys = valleys

            if (pos >= 3) {
                if (prevDiff > 0 && diff < 0) newPeaks++
                else if (prevDiff < 0 && diff > 0) newValleys++
            }

            // Pruning: cannot exceed required peaks/valleys
            if (newPeaks > t || newValleys > t - 1) continue

            dfs(pos + 1, y, newPeaks, newValleys, diff)
        }
    }

    for (y1 in 1..maxY) {
        for (y2 in 1..maxY) {
            if (y2 == y1) continue
            val diff = y2 - y1
            dfs(3, y2, 0, 0, diff)
        }
    }

    println(count)
}

