                        for (y in 1..4) {
                            if (y == prevY) continue // no horizontal segments
                            var nh = h
                            var nv = v
                            var nt = trend

                            if (pos == 2) {
                                // first segment defines initial trend
                                nt = if (y > prevY) 1 else 2
                            } else {
                                if (trend == 1 && y < prevY) {
                                    // up then down -> hump at pos-1
                                    nh++
                                    nt = 2
                                } else if (trend == 2 && y > prevY) {
                                    // down then up -> valley at pos-1
                                    nv++
                                    nt = 1
                                } else {
                                    nt = trend
                                }
                            }

                            if (nh > t || nv >= t) continue
                            dp[pos][y][nh][nv][nt] += curVal
                        }
                    }
                }
            }
        }
    }

    var ans = 0L
    for (y in 1..4) {
        for (trend in 1..2) { // final trend must be defined
            ans += dp[n][y][t][t - 1][trend]
        }
    }

    println(ans)
}

