            if (y1 == y2) continue
            val trend = if (y2 > y1) 1 else 0
            dp[2][y2][0][0][trend]++
        }
    }

    // Transition for positions 3..n
    for (pos in 3..n) {
        for (lastY in 1..4) {
            for (peaks in 0..t) {
                for (valleys in 0 until t) {
                    for (trend in 0..1) {
