                        if (curVal == 0L) continue
                        for (nextY in 1..4) {
                            if (nextY == lastY) continue
                            val nextTrend = if (nextY > lastY) 1 else 0
                            var newPeaks = peaks
                            var newValleys = valleys
                            if (nextTrend != trend) {
                                if (trend == 1) {
                                    // was up, now down -> peak at pos-1
                                    newPeaks++
                                } else {
                                    // was down, now up -> valley at pos-1
                                    newValleys++
                                }
                            }
                            if (newPeaks > t || newValleys >= t) continue
                            dp[pos][nextY][newPeaks][newValleys][nextTrend] += curVal
                        }
                    }
                }
            }
        }
    }

