                            val newTrend = if (newY > lastY) 1 else 0
                            var newPeaks = peaks
                            var newValleys = valleys

                            if (trend != 2) {
                                if (trend == 1 && newTrend == 0) {
                                    // up -> down: possible peak at pos-1
                                    if (pos - 1 in 2..n - 1) {
                                        newPeaks++
                                    }
